.xt-root {
    /* ── 底图图床地址（随时可换） ── */
    --bg-img-url: url('https://s41.ax1x.com/2026/10/27/pnspRds.jpg');

    /* ── 字体与指定色号变量 ── */
    --font-book: 'IM Fell English', 'Cormorant Garamond', 'Noto Serif SC', "Songti SC", serif;
    --font-note: 'Caveat', 'Ma Shan Zheng', "Kaiti SC", STKaiti, cursive, serif;
    --color-book-text: #0d0d0d;      /* 正文统一纯正墨黑色 */
    --color-note-ink: #746E82;       /* 指定的批注手写字 / 波浪线 / 横线颜色 */
    --color-highlighter: rgba(148, 138, 162, 0.48); /* 指定的 #948AA2 荧光笔半透明涂抹色 */

    font-family: var(--font-book);
    color: var(--color-book-text);

    background-image: var(--bg-img-url) !important;
    background-size: cover !important;
    background-position: center center !important;

    border-radius: 20px;
    padding: 16px 14px 28px 14px;
    border: 1px solid rgba(255, 255, 255, 0.35);
    position: relative;

    /* 顺滑上下滚动 */
    max-height: 82vh !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch !important;
}

.xt-root::-webkit-scrollbar { width: 3px; }
.xt-root::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.4);
    border-radius: 4px;
}

/* 底部整体极低透明度浅底（0.38），清晰露出底图 */
.xt-content {
    position: relative;
    z-index: 2;
    overflow: visible !important;
    background: rgba(255, 255, 255, 0.38) !important;
    border-radius: 16px;
    padding: 14px 16px 20px 16px;
    border: 1px solid rgba(255, 255, 255, 0.3);
}

/* ════════════════════════════════════════════
   1. 顶部栏：左上角头像 + 居中完整书名（去掉char名字）
   ════════════════════════════════════════════ */
.xt-header {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    background: transparent !important;
    backdrop-filter: none !important;
    padding: 2px 4px 6px 4px !important;
    border: none !important;
    box-shadow: none !important;
    margin-bottom: 0 !important;
}

/* 左上角：char头像 */
.xt-avatar {
    width: 36px !important;
    height: 36px !important;
    border-radius: 50% !important;
    border: 1.5px solid rgba(255, 255, 255, 0.9) !important;
