:root {
  --chat-bg-color: #f8f7f5;
  --chat-bg-image: none;
  --chat-bg-overlay: transparent;
  --chat-header-bg: #f8f7f5;
  --chat-header-border: #e7e6e3;
  --chat-header-height: 58px;
  --chat-header-title-color: #242424;
  --chat-header-title-size: 19px;
  --chat-header-title-weight: 500;
  --chat-header-icon-color: #252525;
  --bubble-me-radius: 11px 0 11px 11px;
  --bubble-me-shadow: none;
  --bubble-me-border: none;
  --bubble-me-padding: 11px 14px;
  --bubble-them-bg: #fff;
  --bubble-them-color: #171717;
  --bubble-them-radius: 0 11px 11px 11px;
  --bubble-them-shadow: none;
  --bubble-them-border: none;
  --bubble-them-padding: 11px 14px;
  --translation-radius: 10px;
  --timestamp-color: #777672;
  --input-area-bg: #fff;
  --input-area-border-top: none;
  --input-area-padding: 10px 10px;
  --input-box-bg: transparent;
  --input-box-border: none;
  --input-box-shadow: none;
  --input-box-color: #292929;
  --input-box-font-size: 16px;
  --input-caret-color: #777f8a;
  --input-btn-color: #292929;
  --send-btn-bg: #fff;
  --send-btn-color: #383838;
  --stop-btn-bg: #fff;
  --stop-btn-color: #383838;
}

:is(.chat-detail-screen, #chat-detail-screen) {
  background: #f8f7f5 !important;
  color-scheme: light;
}

.chat-messages-area {
  background: #f8f7f5 !important;
}

.chat-header-custom {
  position: relative !important;
  background: radial-gradient(ellipse at 74% 60%, #eaf1e5 0, transparent 56%), #f8f7f5 !important;
  border-bottom: 1px solid #e6e5e1 !important;
  box-shadow: none !important;
}

.chat-header-custom .glass-header {
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}

.header-profile-section {
  flex-direction: row !important;
  justify-content: center !important;
  align-items: center !important;
  gap: 7px !important;
}

.chat-header-title {
  color: #242424 !important;
  font: 500 19px/1.3 -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif !important;
  background: transparent !important;
  box-shadow: none !important;
  border: 0 !important;
}

.chat-header-subtitle {
  display: none !important;
}

.header-btn-back, .header-action-btn {
  color: #292929 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

.header-btn-phone, .header-btn-video {
  display: none !important;
}

.header-btn-info {
  opacity: .35;
}

.header-avatar-container {
  width: 24px !important;
  height: 24px !important;
}

.chat-header-avatar {
  width: 24px !important;
  height: 24px !important;
  border-radius: 50% !important;
}

@supports selector(:has(*)) {
  :is(.chat-detail-screen, #chat-detail-screen) .nuo-typing-indicator {
    display: none !important;
  }

  :is(.chat-detail-screen, #chat-detail-screen):has(.nuo-typing-indicator, .stop-btn-custom) .header-profile-section > * {
    visibility: hidden !important;
  }

  :is(.chat-detail-screen, #chat-detail-screen):has(.nuo-typing-indicator, .stop-btn-custom) .header-profile-section {
    position: absolute !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%) !important;
    width: max-content !important;
    max-width: calc(100% - 100px) !important;
    pointer-events: none;
  }

  :is(.chat-detail-screen, #chat-detail-screen):has(.nuo-typing-indicator, .stop-btn-custom) .header-profile-section::before {
    content: '';
    position: absolute;
    width: 45px;
    height: 34px;
    left: 0;
    background: var(--maybe-cat) center / contain no-repeat;
  }

  :is(.chat-detail-screen, #chat-detail-screen):has(.nuo-typing-indicator, .stop-btn-custom) .header-profile-section::after {
    content: 'Typing... maybe.';
    position: absolute;
    left: 53px;
    white-space: nowrap;
    font: 400 clamp(16px, 4.8vw, 21px)/1.2 -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #252525;
  }
}

.bubble-me-custom {
  border-radius: 11px 0 11px 11px !important;
  box-shadow: none !important;
}

.bubble-them-custom {
  background: #fff !important;
  border-radius: 0 11px 11px 11px !important;
  box-shadow: none !important;
}

.msg-avatar-them-container, .msg-avatar-me-container {
  display: none !important;
}

.timestamp-custom {
  display: flex !important;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: #777672 !important;
  background: none !important;
  font-size: 13px !important;
  border: none !important;
  box-shadow: none !important;
}

.timestamp-custom::before, .timestamp-custom::after {
  content: '';
  width: 44px;
  height: 1px;
  background: linear-gradient(90deg, transparent, #dcdad6);
}

.timestamp-custom::after {
  transform: rotate(180deg);
}

.input-area-custom {
  position: relative !important;
  background: #fff !important;
  border-radius: 24px 24px 0 0 !important;
  border-top: 1px solid #f1f0ee !important;
  padding: 10px 10px max(14px, env(safe-area-inset-bottom)) !important;
  box-shadow: 0 -2px 8px #302a2110 !important;
}

.input-row-wrapper {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  min-height: 54px;
  padding: 0 !important;
  gap: 0 !important;
  border-radius: 999px !important;
  background: #ecebe9 !important;
}

.input-action-bar-custom {
  position: relative !important;
  flex: 1 !important;
  width: 100% !important;
  min-width: 0 !important;
  min-height: 54px !important;
  margin: 0 !important;
  padding: 5px 94px 5px 56px !important;
  border: none !important;
  border-radius: 999px !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible !important;
}

.input-box-custom {
  min-width: 0 !important;
  width: 100% !important;
  padding: 6px 3px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 16px !important;
  line-height: 22px !important;
}

.input-box-custom::placeholder {
  color: transparent !important;
}

.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::after {
  content: 'write for sth..';
  position: absolute;
  left: 59px;
  top: 50%;
  transform: translateY(-50%);
  color: #a29f99;
  font: 400 16px/1.2 -apple-system, BlinkMacSystemFont, sans-serif;
  pointer-events: none;
}

.input-btns-right {
  position: static !important;
  gap: 0 !important;
}

.input-btn-mic {
  position: absolute !important;
  left: 5px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 44px !important;
  height: 44px !important;
  min-width: 44px !important;
  padding: 0 !important;
  border-radius: 50% !important;
  border: 1px solid #e0e4e5 !important;
  background: radial-gradient(circle at 70% 80%, #fff, #e8eff1) !important;
  box-shadow: 3px 4px 10px #a8a6a633, inset 0 1px 2px #fff !important;
}

.input-btn-mic svg {
  opacity: 0 !important;
}

.input-btn-mic::after {
  content: '';
  position: absolute;
  inset: 9px;
  background: var(--maybe-wave) center / contain no-repeat;
}

.input-row-wrapper .input-btn-plus {
  position: absolute !important;
  right: 11px !important;
  left: auto !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  z-index: 3;
  width: 79px !important;
  min-width: 79px !important;
  height: 33px !important;
  padding: 0 !important;
  border: 1px solid #e2e1de !important;
  border-radius: 999px !important;
  background: #fff var(--maybe-tools) center / 68px 26px no-repeat !important;
  box-shadow: none !important;
}

.input-btn-plus svg {
  opacity: 0 !important;
}

.input-btn-sticker, .input-btn-ai {
  display: none !important;
}

.input-row-wrapper:has(.send-btn-custom, .stop-btn-custom) .input-btn-plus {
  right: 47px !important;
  width: 34px !important;
  min-width: 34px !important;
  background: #fff !important;
}

.input-row-wrapper:has(.send-btn-custom, .stop-btn-custom) .input-btn-plus svg {
  opacity: 1 !important;
}

.send-btn-custom, .stop-btn-custom {
  position: absolute !important;
  right: 8px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 34px !important;
  height: 34px !important;
  padding: 7px !important;
  border-radius: 50% !important;
  background: #fff !important;
  color: #363636 !important;
}

:root {
  --maybe-cat: var(--tm-asset-1);
  --maybe-wave: var(--tm-asset-2);
  --maybe-tools: var(--tm-asset-3);
}

.chat-header-custom .header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  width: max-content !important;
  max-width: calc(100% - 110px) !important;
  margin: 0 !important;
}

.chat-header-custom :is(.header-btn-phone, .header-btn-video, .header-btn-info) {
  display: inline-flex !important;
  opacity: 0 !important;
  visibility: visible !important;
  pointer-events: auto !important;
}

.input-row-wrapper .input-btn-plus,
.input-row-wrapper:has(.send-btn-custom, .stop-btn-custom) .input-btn-plus {
