/* 消除未展开翻译的占位，保留透明翻译按钮的原点击处理器。 */
:is(.bubble-me-custom, .bubble-them-custom) .msg-translation-wrapper {
  display: contents !important;
  min-height: 0 !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
}
/* 翻译可能套在正文容器内，移除该容器额外的 flex/grid 行间距。 */
:is(.bubble-me-custom, .bubble-them-custom):has(> .msg-translation-wrapper),
:is(.bubble-me-custom, .bubble-them-custom) :has(> .msg-translation-wrapper) {
  row-gap: 0 !important;
}
:is(.bubble-me-custom, .bubble-them-custom) .msg-translation-content {
  min-height: 0 !important;
  margin: 2px 0 0 !important;
  padding: 0 !important;
}
:is(.bubble-me-custom, .bubble-them-custom) .msg-translation-content:empty {
  display: none !important;
  margin: 0 !important;
}
